#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int value; struct Node *next; } Node;
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    Node *head = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) return 1;
        Node *nd = malloc(sizeof(Node));
        nd->value = x;
        nd->next = head;
        head = nd;
    }
    for (Node *cur = head; cur; ) {
        printf("%d", cur->value);
        Node *next = cur->next;
        free(cur);
        cur = next;
        if (cur) printf(" ");
    }
    printf("\n");
    return 0;
}
